def max_value_on_paths(N: int, grid_values: list) -> int:
    """Calculate the maximum sum of values collected on two paths in an N x N grid."""
    # Build grid with 1‑based indices
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, v in grid_values:
        if x == 0 and y == 0 and v == 0:
            break
        grid[x][y] = v

    # dp arrays: prev and cur
    neg_inf = -10 ** 18
    prev = [[neg_inf] * (N + 1) for _ in range(N + 1)]
    # start at (1,1) for both
    prev[1][1] = grid[1][1]

    # step k = row + col
    for k in range(3, 2 * N + 1):
        cur = [[neg_inf] * (N + 1) for _ in range(N + 1)]
        for i in range(1, N + 1):
            j = k - i
            if j < 1 or j > N:
                continue
            for x in range(1, N + 1):
                y = k - x
                if y < 1 or y > N:
                    continue
                best = neg_inf
                # iterate over previous positions for both paths
                for pi in (i - 1, i):
                    if pi < 1 or pi > N:
                        continue
                    pj = (k - 1) - pi
                    if pj < 1 or pj > N:
                        continue
                    for px in (x - 1, x):
                        if px < 1 or px > N:
                            continue
                        py = (k - 1) - px
                        if py < 1 or py > N:
                            continue
                        cand = prev[pi][px]
                        if cand == neg_inf:
                            continue
                        if i == x:
                            cand += grid[i][j]
                        else:
                            cand += grid[i][j] + grid[x][y]
                        if cand > best:
                            best = cand
                cur[i][x] = best
        prev = cur

    return prev[N][N] if prev[N][N] != neg_inf else 0

