def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
        encoded (str): A string representing the encoded information.
        original (str): A string representing the original information corresponding to the encoded string.
        message (str): A string representing the encrypted message to be decoded.

    Returns:
        str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e_char, o_char in zip(encoded, original):
        if e_char in mapping:
            if mapping[e_char] != o_char:
                return "Failed"
        else:
            mapping[e_char] = o_char

    # Ensure the mapping covers all 26 uppercase letters (A-Z)
    if len(mapping) < 26:
        return "Failed"

    decoded_chars = []
    for c in message:
        if c in mapping:
            decoded_chars.append(mapping[c])
        else:
            return "Failed"

    return ''.join(decoded_chars)

def count_partitions(n: int, k: int, x: int) -> int:
    """
    Count the number of ways to partition an integer `n` into exactly `k` parts,
    where each part is at least `x` and the order of parts does not matter.
    """
    # Subtract the minimum value from each part
    remaining = n - k * x
    if remaining < 0:
        return 0
    if k == 0:
        return 1 if remaining == 0 else 0

    # dp[s][p] = number of partitions of s using parts of size at most p
    dp = [[0] * (k + 1) for _ in range(remaining + 1)]

    # Base case: one way to partition 0 (empty partition)
    for p in range(k + 1):
        dp[0][p] = 1

    for s in range(1, remaining + 1):
        for p in range(1, k + 1):
            if p > s:
                dp[s][p] = dp[s][p - 1]
            else:
                dp[s][p] = dp[s][p - 1] + dp[s - p][p]

    return dp[remaining][k]

def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of ordered pairs (P, Q) of positive integers such that
    gcd(P, Q) == x0 and lcm(P, Q) == y0.
    """
    if x0 <= 0 or y0 <= 0 or y0 % x0 != 0:
        return 0

    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    k = y0 // x0
    count = 0
    a = 1
    while a * a <= k:
        if k % a == 0:
            b = k // a
            if _gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
        a += 1

    return count

def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of ordered pairs of positive integers (P, Q) such that
    gcd(P, Q) == x0 and lcm(P, Q) == y0.
    """
    if x0 <= 0 or y0 <= 0:
        return 0
    # The LCM must be a multiple of the GCD; otherwise no pairs exist.
    if y0 % x0 != 0:
        return 0

    m = y0 // x0  # We need a * b = m and gcd(a, b) == 1

    # Helper to compute GCD without import
    def gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    count = 0
    limit = int(m ** 0.5)
    for a in range(1, limit + 1):
        if m % a == 0:
            b = m // a
            if gcd(a, b) == 1:
                if a == b:
                    count += 1     # (P, Q) and (Q, P) are the same
                else:
                    count += 2     # (P, Q) and (Q, P) are distinct

    return count

def preorder_traversal(inorder: str, postorder: str) -> str:
    n = len(inorder)
    pos = {ch: i for i, ch in enumerate(inorder)}

    def helper(in_l: int, in_r: int, post_l: int, post_r: int) -> str:
        if in_l > in_r:
            return ''
        root = postorder[post_r]
        idx = pos[root]
        left_size = idx - in_l
        left_pre = helper(in_l, idx - 1, post_l, post_l + left_size - 1)
        right_pre = helper(idx + 1, in_r, post_l + left_size, post_r - 1)
        return root + left_pre + right_pre

    return helper(0, n - 1, 0, n - 1)

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to 10 steps to find minimal steps or return "NO ANSWER!" if impossible.
    """
    if A == B:
        return 0

    from collections import deque

    visited = {A}
    queue = deque([(A, 0)])

    while queue:
        current, steps = queue.popleft()
        if steps >= 10:
            continue
        for src, tgt in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str == B:
                    return steps + 1
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                start = idx + 1  # allow overlapping matches

    return "NO ANSWER!"

