def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    import re

    # Regular expressions to parse statements
    guilty_rx = re.compile(r'^\s*(?P<subject>\w+)\s+is\s+guilty\.?$|^\s*I\s+am\s+guilty\.?$', re.I)
    not_guilty_rx = re.compile(r'^\s*(?P<subject>\w+)\s+is\s+not\s+guilty\.?$|^\s*I\s+am\s+not\s+guilty\.?$', re.I)

    days_lower = {d.lower() for d in days_of_week}

    for speaker, stmts in statements.items():
        for stmt in stmts:
            # Skip statements that mention a day of the week
            stmt_low = stmt.lower()
            if any(day in stmt_low for day in days_lower):
                continue

            subject = None
            is_guilty = None

            m = guilty_rx.match(stmt)
            if m:
                is_guilty = True
                subject = m.group('subject')
            else:
                m = not_guilty_rx.match(stmt)
                if m:
                    is_guilty = False
                    subject = m.group('subject')

            # If statement doesn't match known patterns, skip it
            if subject is None or is_guilty is None:
                continue

            # Resolve 'I' subject to the speaker's name
            if subject.lower() == 'i':
                subject = speaker

            # Determine if the statement is true given the scenario
            truth = (subject == scenario) if is_guilty else (subject != scenario)

            # Check consistency with liar status
            if speaker in liar_count and truth:
                return False          # liar told a true statement
            if speaker not in liar_count and not truth:
                return False          # truth teller told a false statement

    return True

def remaining_trees_after_clearing(l: int, areas: list[tuple[int, int]]) -> int:
    if not areas:
        return l
    # Merge overlapping or adjacent ranges (treating [start, end) as cleared)
    cleaned = []
    for start, end in sorted(areas, key=lambda x: x[0]):
        if cleaned and start <= cleaned[-1][1]:
            cleaned[-1] = (cleaned[-1][0], max(cleaned[-1][1], end))
        else:
            cleaned.append((start, end))
    # Total length cleared
    cleared_len = sum(e - s for s, e in cleaned)
    remaining = l - cleared_len
    return remaining if remaining > 0 else 0

def remaining_trees_after_clearing(l: int, areas: List[Tuple[int, int]]) -> int:
    if l <= 0:
        return 0
    if not areas:
        return l
    # Normalize intervals to [start, end) within [0, l)
    normalized = []
    for s, e in areas:
        if e <= s:
            continue
        s = max(s, 0)
        e = min(e, l)
        if s >= e:
            continue
        normalized.append((s, e))
    if not normalized:
        return l
    normalized.sort(key=lambda x: x[0])
    merged = []
    cur_start, cur_end = normalized[0]
    for s, e in normalized[1:]:
        if s <= cur_end:  # overlap
            cur_end = max(cur_end, e)
        else:
            merged.append((cur_start, cur_end))
            cur_start, cur_end = s, e
    merged.append((cur_start, cur_end))
    covered = sum(end - start for start, end in merged)
    remaining = l - covered
    return remaining if remaining >= 0 else 0

