def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    :param heights: List[int] - a list of student heights
    :return: int - the minimum number of students that need to leave
    """
    n = len(heights)
    if n <= 2:
        # With one or two students we can always form a bitonic sequence
        return 0

    # Compute LIS (Longest Increasing Subsequence) lengths ending at each index
    inc = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and inc[j] + 1 > inc[i]:
                inc[i] = inc[j] + 1

    # Compute LDS (Longest Decreasing Subsequence) lengths starting at each index
    dec = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and dec[j] + 1 > dec[i]:
                dec[i] = dec[j] + 1

    # Find the maximum length of a bitonic subsequence
    max_bitonic = 0
    for i in range(n):
        # Subtract 1 to avoid double counting the peak element
        bitonic_len = inc[i] + dec[i] - 1
        if bitonic_len > max_bitonic:
            max_bitonic = bitonic_len

    # Minimum deletions to obtain a bitonic sequence
    return n - max_bitonic

def hanoi_double_iterative(n: int) -> int:
    """Return the minimal number of moves for the double‑disc Tower of Hanoi (2n discs)."""
    moves = 0
    for _ in range(n):
        moves = moves * 2 + 2
    return moves
